'use client'
import { useSignal, useSignalEffect, useSignals } from '@cascivo/core'
import type { Signal } from '@cascivo/core'
import type { RefObject } from 'react'
import type { TocItem } from './toc'

export interface UseTocFromRegionOptions {
  /** CSS selector for the headings to collect. Defaults to `h2, h3, h4`. */
  selector?: string
}

/**
 * Opt-in convenience: derive a `TocItem[]` signal from the headings inside a
 * container. Headings must have an `id`. Feed the result to `<Toc items={…} />`.
 * The controlled `items` API on `Toc` remains the primary, testable surface;
 * this helper only builds the list.
 */
export function useTocFromRegion(
  ref: RefObject<HTMLElement | null>,
  options: UseTocFromRegionOptions = {},
): Signal<TocItem[]> {
  // Self-subscribe so a plain React consumer that reads the returned signal in
  // render re-renders as headings are collected without calling useSignals() itself.
  useSignals()
  const selector = options.selector ?? 'h2, h3, h4'
  const items = useSignal<TocItem[]>([])

  useSignalEffect(() => {
    const root = ref.current
    if (!root) return
    const headings = Array.from(root.querySelectorAll<HTMLElement>(selector))
    items.value = headings
      .filter((h) => h.id !== '')
      .map((h) => ({
        id: h.id,
        label: h.textContent?.trim() ?? '',
        level: Number(h.tagName.slice(1)) || 2,
      }))
  })

  return items
}

@layer cascivo.component {
  .toc {
    font-family: var(--cascivo-font-sans);
    font-size: var(--cascivo-text-sm);
    line-height: var(--cascivo-leading-snug);

    & ol {
      display: flex;
      flex-direction: column;
      margin: 0;
      padding: 0;
      list-style: none;
    }

    /* Indent by heading level: level 2 is the base, each deeper level steps in. */
    & li {
      padding-inline-start: calc((var(--toc-level, 2) - 2) * var(--cascivo-space-3));
    }

    & a {
      display: block;
      padding-block: var(--cascivo-space-1);
      padding-inline: var(--cascivo-space-2);
      color: var(--cascivo-color-text-muted);
      text-decoration: none;
      border-inline-start: 2px solid transparent;
      transition: color var(--cascivo-duration-150) var(--cascivo-ease-out);

      &:hover {
        color: var(--cascivo-color-text);
      }

      &:focus-visible {
        outline: none;
        box-shadow: var(--cascivo-focus-ring);
        border-radius: var(--cascivo-radius-sm);
      }
    }

    & a[aria-current='location'] {
      color: var(--cascivo-color-accent-text);
      border-inline-start-color: var(--cascivo-color-accent);
      font-weight: var(--cascivo-font-medium);
    }

    /* Touch: keep tap targets ≥44px on coarse pointers without affecting desktop. */
    @media (pointer: coarse) {
      & a {
        display: flex;
        align-items: center;
        min-block-size: var(--cascivo-target-min-coarse, 2.75rem);
      }
    }
  }
}

